DROP TABLE IF EXISTS `attendances`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `attendances` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `user_id` bigint unsigned NOT NULL,
  `user_machine_code` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `user_department` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `course_category_id` bigint unsigned DEFAULT NULL,
  `course_category_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `course_id` bigint unsigned NOT NULL,
  `course_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `course_hours` bigint DEFAULT '0',
  `section_id` bigint unsigned DEFAULT NULL,
  `attendance_hours` double(8,2) DEFAULT '0.00',
  `is_manual` tinyint(1) DEFAULT '0',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=5869 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;
/*!40101 SET character_set_client = @saved_cs_client */;

