/*!40000 ALTER TABLE `courses` DISABLE KEYS */;
INSERT INTO `courses` VALUES (6,'online','Selling Skills Course','Selling Skills Course','<p>Selling Skills Course</p>','Course/848zrf3DK9If8PTXrLBhce18fbe8cdcf7122650c09812e7025bc.png',1,NULL,NULL,NULL,10,NULL,'beginner',1,0,0,1,0,NULL,1,'2025-11-05 10:09:25','2026-02-11 12:44:21'),(8,'offline','Self-motivation Course','Self-motivation Course','<p>&nbsp;&nbsp;</p>','Course/HTE3hV6DaFtHd4iTg94Efe55a2e42ba5fbd4a8cbdf2b8693c6fb.jpg',5,NULL,NULL,NULL,8,NULL,'medium',1,0,0,1,0,NULL,1,'2025-12-04 10:09:01','2026-02-12 09:00:38'),(10,'offline','Teamwork','Teamwork Course','<p><strong><span style=\"font-size: 14pt;\">وصف الدورة:</span></strong><br data-start=\"82\" data-end=\"85\" /><span style=\"font-size: 14pt;\">تهدف هذه الدورة إلى تنمية مهارات العمل الجماعي وتعزيز التعاون بين أفراد الفريق، من خلال تحسين التواصل، وبناء الثقة، والتعامل الإيجابي مع الاختلافات لتحقيق الأهداف المشتركة ورفع مستوى الأداء.</span></p>','Course/w44DhtWirProj66V0cFVd0682250593945eba1fb992c406c6a54.jpg',5,NULL,NULL,NULL,8,NULL,'beginner',1,0,0,1,0,NULL,1,'2025-12-15 08:58:22','2026-02-12 09:01:48'),(11,'offline','Critical& Creative Thinking','Critical& Creative Thinking','<div class=\"flex flex-col text-sm pb-25\">\r\n<article class=\"text-token-text-primary w-full focus:outline-none [--shadow-height:45px] has-data-writing-block:pointer-events-none has-data-writing-block:-mt-(--shadow-height) has-data-writing-block:pt-(--shadow-height) [&amp;:has([data-writing-block])&gt;*]:pointer-events-auto [content-visibility:auto] supports-[content-visibility:auto]:[contain-intrinsic-size:auto_100lvh] scroll-mt-[calc(var(--header-height)+min(200px,max(70px,20svh)))]\" dir=\"auto\" tabindex=\"-1\" data-turn-id=\"request-WEB:de38b6b6-45c3-463b-b4d3-02e44d82232b-0\" data-testid=\"conversation-turn-2\" data-scroll-anchor=\"true\" data-turn=\"assistant\">\r\n<div class=\"text-base my-auto mx-auto pb-10 [--thread-content-margin:--spacing(4)] @w-sm/main:[--thread-content-margin:--spacing(6)] @w-lg/main:[--thread-content-margin:--spacing(16)] px-(--thread-content-margin)\">\r\n<div class=\"[--thread-content-max-width:40rem] @w-lg/main:[--thread-content-max-width:48rem] mx-auto max-w-(--thread-content-max-width) flex-1 group/turn-messages focus-visible:outline-hidden relative flex w-full min-w-0 flex-col agent-turn\" tabindex=\"-1\">\r\n<div class=\"flex max-w-full flex-col grow\">\r\n<div class=\"min-h-8 text-message relative flex w-full flex-col items-end gap-2 text-start break-words whitespace-normal [.text-message+&amp;]:mt-1\" dir=\"auto\" data-message-author-role=\"assistant\" data-message-id=\"d10954a0-c21d-46e7-89f7-71d55a9243f7\" data-message-model-slug=\"gpt-5-2\">\r\n<div class=\"flex w-full flex-col gap-1 empty:hidden first:pt-[1px]\">\r\n<div class=\"markdown prose dark:prose-invert w-full break-words light markdown-new-styling\">\r\n<p data-start=\"75\" data-end=\"428\" data-is-last-node=\"\" data-is-only-node=\"\"><span style=\"font-size: 12pt; font-family: \'comic sans ms\', sans-serif;\">تهدف دورة <em data-start=\"101\" data-end=\"127\">التفكير النقدي والإبداعي</em> إلى تنمية قدرة المشاركين على تحليل المواقف والمعلومات بشكل منطقي وموضوعي، وتجنب الأخطاء الشائعة في التفكير، مع تعزيز مهارات توليد الأفكار الجديدة والحلول المبتكرة. تركز الدورة على الدمج بين التفكير التحليلي والتفكير خارج الصندوق لمواجهة المشكلات بفعالية واتخاذ قرارات أفضل في الحياة المهنية والعملية.</span></p>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</article>\r\n</div>','Course/2HZNM8y16kWyA2d4Bb8I234ae50651cc75bb7b5759f85904d7aa.jpg',5,NULL,NULL,NULL,8,NULL,'beginner',1,0,0,1,0,NULL,1,'2025-12-22 09:58:59','2026-02-12 09:02:27'),(14,'online','اختبار تحديد مستوي في الاكسل','اختبار تحديد مستوي في الاكسل','<p>اختبار تحديد مستوي في الاكسل</p>','Course/VqZtbh0xmiEYyaL4vbua6c47cca2e405a93606cc03b2f9dd8af8.png',6,NULL,NULL,NULL,NULL,NULL,'beginner',0,1,0,1,0,NULL,1,'2025-12-29 12:07:50','2026-04-30 08:21:33'),(15,'online','اختبار تحديد مستوي في الاكسيل المستوي المتقدم','اختبار تحديد مستوي في الاكسيل المستوي المتقدم','<p>اختبار تحديد مستوي في الاكسيل المستوي المتقدم</p>','Course/xyKZNAg4jFxCqYij52MR5818261fc08ed8200bc2b4f661e0c88a.png',6,NULL,NULL,NULL,0,NULL,'professional',0,1,0,1,0,NULL,1,'2025-12-30 11:49:03','2026-02-10 13:11:43'),(16,'offline','Tme Management Course','Time Management Course','<p>يهدف كورس <strong data-start=\"117\" data-end=\"150\">إدارة الوقت (Time Management)</strong> إلى مساعدة المتدربين على استغلال وقتهم بشكل أكثر كفاءة وفعالية، من خلال التعرف على أهم مفاهيم إدارة الوقت، وتحديد الأولويات، والتخطيط الجيد للمهام اليومية.<br data-start=\"306\" data-end=\"309\" />يتعلم المشاركون كيفية التغلب على مضيعات الوقت، وتنظيم العمل، وتحقيق التوازن بين متطلبات العمل والحياة الشخصية، مما ينعكس بشكل إيجابي على الإنتاجية والأداء العام.</p>\r\n<p style=\"text-align: left;\">The <strong data-start=\"95\" data-end=\"114\">Time Management</strong> course helps participants manage their time better and work more efficiently.<br data-start=\"192\" data-end=\"195\" />It focuses on how to plan daily tasks, set priorities, and avoid time wasters.<br data-start=\"273\" data-end=\"276\" />By the end of the course, participants will be able to organize their work, reduce stress, and achieve better results within their working hours.</p>','Course/HswuQ3Drh2HTIHKPhSBVdcb3210811b4172c00a6777dd8645b9a.jpg',1,NULL,NULL,NULL,8,NULL,'beginner',1,0,0,1,0,NULL,0,'2026-01-04 16:35:15','2026-02-12 09:02:49'),(17,'offline','Emotional Intelligence Course g1','Emotional Intelligence Course','<p class=\"isSelectedEnd\">يهدف هذا الكورس إلى تنمية مهارات الذكاء العاطفي لمساعدة المشاركين على فهم مشاعرهم وإدارتها بشكل أفضل، بالإضافة إلى التعرف على مشاعر الآخرين والتعامل معها بفعالية. يتناول الكورس العناصر الأساسية للذكاء العاطفي مثل الوعي الذاتي، التحكم في الانفعالات، التحفيز، التعاطف، والمهارات الاجتماعية.</p>\r\n<p>من خلال أمثلة عملية ونقاشات وأنشطة تطبيقية، سيتعلم المشاركون كيف يساهم الذكاء العاطفي في تحسين التواصل، والعمل الجماعي، والقيادة، وبناء علاقات إيجابية داخل بيئة العمل، مما ينعكس على الأداء واتخاذ القرارات بشكل أفضل.</p>\r\n<p class=\"isSelectedEnd\">This course focuses on developing Emotional Intelligence skills to help participants better understand and manage their own emotions, as well as recognize and respond effectively to the emotions of others. The course covers key EI components such as self-awareness, self-regulation, motivation, empathy, and social skills.</p>\r\n<p>Through practical examples, discussions, and activities, participants will learn how emotional intelligence improves communication, teamwork, leadership effectiveness, and workplace relationships, leading to better performance and decision-making</p>','Course/fybiogGYMR4YbePH5oKI87f899f098ab6ffd883924e7ebe2c458.jpg',1,NULL,NULL,NULL,8,NULL,'beginner',1,0,0,1,0,NULL,1,'2026-01-08 16:14:15','2026-02-12 09:05:52'),(18,'offline','Negotiation skills course','Negotiation skills course','<p class=\"isSelectedEnd\">يهدف كورس <strong>مهارات التفاوض (Negotiation Skills)</strong> إلى تزويد المشاركين بالمعرفة والمهارات العملية اللازمة لإدارة المفاوضات باحترافية وتحقيق أفضل النتائج الممكنة لجميع الأطراف.<br />يركز الكورس على فهم مبادئ التفاوض، وأنماطه المختلفة، وكيفية الاستعداد الجيد للمفاوضات، وبناء الحجج القوية، وإدارة الاعتراضات، والتعامل مع المواقف الصعبة بثقة وذكاء.</p>\r\n<p>كما يساعد الكورس المتدربين على تحسين مهارات التواصل، قراءة لغة الجسد، التحكم في المشاعر أثناء التفاوض، والوصول إلى حلول رابحة (Win-Win).<br />الكورس مناسب للموظفين، قادة الفرق، مندوبي المبيعات، وكل من يتعامل مع التفاوض في بيئة العمل.</p>\r\n<p>&nbsp;</p>\r\n<p class=\"isSelectedEnd\" style=\"text-align: left;\">the <strong>Negotiation Skills Course</strong> aims to equip participants with the essential knowledge and practical skills needed to conduct negotiations professionally and achieve optimal outcomes for all parties involved.<br />The course focuses on understanding negotiation principles and styles, effective preparation, building strong arguments, handling objections, and managing challenging situations with confidence.</p>\r\n<p style=\"text-align: left;\">Participants will also enhance their communication skills, learn how to read body language, manage emotions during negotiations, and reach win-win solutions.<br />This course is ideal for employees, team leaders, sales professionals, and anyone involved in negotiations in the workplace.</p>','Course/lRinslolrsVM6vw19sTK466e7d2eff6d5882957c829d2f9ed090.jpg',1,NULL,NULL,NULL,8,NULL,'beginner',1,0,0,1,0,NULL,1,'2026-01-11 10:29:51','2026-02-12 09:06:27'),(20,'offline','Selling Skills','Selling Skills Course','<p style=\"direction: ltr;\">Selling Skills</p>','Course/YwMhujSRZa0zquX2xrZ9afc503badeb8fcb12d84ea4bf33b616f.png',1,NULL,NULL,NULL,10,NULL,'beginner',1,1,0,1,1,NULL,1,'2026-02-10 14:44:08','2026-06-24 13:30:21'),(21,'offline','Supply Chain Course','Supply Chain Course','<p style=\"text-align: left;\">This course aims to introduce complex Supply chain management concepts, drivers, and models. We will address the basic concepts of operations management, such as lean, inventory planning, forecasting, and Lean/Six Sigma</p>\r\n<p style=\"text-align: left;\"><strong>Learning Outcomes:</strong></p>\r\n<ul style=\"text-align: left;\">\r\n<li>\r\n<p style=\"direction: ltr;\">&bull; Develop comprehensive strategies that align supply chain operations with overall corporate goals and competitive priorities.</p>\r\n<p style=\"direction: ltr;\">&bull; Formulate, analyze, and design a complex supply chain network.</p>\r\n<p style=\"direction: ltr;\">&bull; Develop advanced negotiation techniques, supplier relationship management (SRM), and category management to enhance value beyond simple price reduction.</p>\r\n<p style=\"direction: ltr;\">&bull; Understand lean systems, continuous improvement</p>\r\n<p style=\"direction: ltr;\">&bull; Understand inventory and pricing models.</p>\r\n</li>\r\n</ul>','Course/kCrCJg1j8th8DMJ7xCUD2f88468669deeef28326477addb8d611.png',7,NULL,NULL,NULL,33,NULL,'professional',1,1,0,0,1,NULL,1,'2026-02-11 12:41:36','2026-04-05 09:48:18'),(22,'offline','(Ahmed Awad) Business English','Business English','<p>aa</p>','Course/AC6piPlR9jUhGejc6pZuf64e0956cedc038e54dad15d73c73236.png',8,NULL,NULL,NULL,21,NULL,'medium',1,1,0,0,1,NULL,1,'2026-02-11 13:23:59','2026-05-12 11:37:13'),(23,'offline','English Course – Level 5- Ahmed Awad','English Course – Level 5','<p>English Course &ndash; Level 5</p>','Course/4U1aDeXcyWhhpcPdtgdib75e8a7b334fe4b8efb1c1a6c0c790a9.png',8,NULL,NULL,NULL,21,NULL,'medium',1,1,0,0,1,'Course Name: English Course  Level 5\r\nSession Day: Every Wednesday at 2:00 p.m.\r\nInstructor: Mr. Ahmed Awad\r\nInstructions:\r\nPlease use the link below to access 2B Academy:\r\nhttps://2b-academy.com/\r\n\r\nYou are required to register your attendance by clicking the attendance button once per session you attend.\r\n\r\nIf you do not attend a session, please do not click the attendance button. Only register attendance for sessions you have actually attended.\r\n\r\nIf you have any inquiries or need assistance, please contact me at 01115729032.',1,'2026-02-11 14:38:31','2026-04-05 09:52:25'),(25,'online','خطط تقسيط فاليو والعروض','خطط تقسيط فاليو والعروض','<p>خطط تقسيط فاليو والعروض</p>','Course/PiUIveSMWWO8bPFZTNUF470d59965b938f76963743ad4c5d03c8.png',4,NULL,NULL,NULL,1,NULL,'medium',0,1,0,1,0,'صباح الفل 🌞\r\nعندنا عرض جديد مع فاليو يومي 13 و14 فبراير 🎉\r\nعشان تبقى عارف كل تفاصيل العرض وتطبّقه صح في الفرع، امشي على الخطوات دي 👇\r\n\r\n🔗 ادخل على أكاديمية تو بي:\r\nhttps://2b-academy.com/\r\n\r\n👤 سجّل دخول بـ:\r\n• الكود الوظيفي\r\n• نفس الباسورد بتاع أبلكيشن الـ الاتش أر\r\n\r\n📚 بعد ما تدخل:\r\n1️⃣ اختار \"دوراتي\"\r\n2️⃣ افتح كورس \"خطط تقسيط فاليو والعروض\"\r\n3️⃣ اتفرج على الفيديو للآخر 🎥\r\n4️⃣ اقرأ ملف العرض كويس جدًا 📄\r\n5️⃣ حلّ الامتحان ✅\r\n\r\n⚠️ مهم جدًا تخلص كل الخطوات دي النهاردة  علشان تبقى فاهم تفاصيل العرض وتعرف تشرحه للعميل بثقة.\r\n\r\nبالتوفيق يا أبطال 💪🔥',0,'2026-02-12 09:49:30','2026-04-29 10:25:28'),(27,'offline','IFRS- INACT','IFRS','<p>IFRS</p>','Course/QxH32TRqcpH0sGx3SxXk0fc3dfb3711ced8577de0a24f94779b8.jpg',10,NULL,NULL,NULL,108,NULL,'professional',0,1,0,1,1,NULL,0,'2026-02-12 14:20:02','2026-02-12 14:20:02'),(28,'offline','English Course Level 1(Ms. Heba)','English Course Level1','<p>English Course Level 2(Ms. Heba)</p>','Course/V5JLW9bNCmW98ZKRjnx25e68b19743bfb23f19e648e131c0854c.png',8,NULL,NULL,NULL,30,NULL,'medium',1,1,0,0,1,NULL,0,'2026-02-12 15:17:09','2026-04-23 15:01:50'),(29,'offline','Organization Development Practitioners Certificate','Organization Development Practitioners Certificate','<p>The OD Practitioners (ODP) is a comprehensive and authoritative learning organization supporting the broad OD Practitioners specially and Human Resources Professionals Community Generally across foundational education, career expertise, and professional development.</p>','Course/jcsO789LuoQIXtYD3Ynp6a9d8ee1537c6f48b9a8e0b06533ce5a.jfif',11,NULL,NULL,NULL,54,NULL,'professional',1,1,0,1,1,NULL,0,'2026-02-13 12:14:22','2026-02-13 13:11:17'),(30,'offline','Product knowledge for newcomers','Product knowledge for newcomers','<p>Product knowledge for newcomers</p>','Course/MFPJ8oMTFYUUzL1JNabvb45f63f2a9c75786d4cb79ab3a150d11.jfif',1,NULL,NULL,NULL,40,NULL,'beginner',1,1,0,0,1,NULL,1,'2026-02-16 12:26:22','2026-06-20 14:31:17'),(31,'offline','Xiaomi','Xiaomi','<p>Xiaomi Note 15 Series</p>','Course/NWLzuondbDdcecBqzqimed0a79367c49c9fa0fc75bb2cea163a4.png',3,NULL,NULL,NULL,2,NULL,'medium',0,1,0,1,1,'مساء الخير يا شباب 🌟\r\n\r\nعلشان تسجلوا حضور سيشن النهاردة – Xiaomi Note 15 Series Training:\r\n\r\n1️⃣ ادخلوا على موقع الأكاديمية:\r\nhttps://2b-academy.com/\r\n\r\n2️⃣ اعملوا تسجيل دخول باستخدام الكود الوظيفي وباسورد تطبيق الـ HR\r\n\r\n3️⃣ ادخلوا على «دوراتي»\r\n4️⃣ سجلوا الحضور من الزرار الأخضر ✅',1,'2026-02-17 09:13:42','2026-02-17 15:46:40'),(32,'offline','Basic Excel Course','Basic Excel Course','<p>Basic Excel Course</p>','Course/j8RrSG22zglyln6Z803E56ec5615afa72