INSERT INTO `evaluations` VALUES (1,2,'five','إلى أي مدى كانت أهداف البرنامج واضحة لك من البداية؟',1,'2026-02-11 15:16:26','2026-02-11 15:25:41'),(2,2,'five','إلى أي مدى كان المحتوى مرتبطًا بطبيعة عملك؟',1,'2026-02-11 15:26:01','2026-02-11 15:26:01'),(3,2,'five','كيف تقيّم تنظيم وتسلسل الموضوعات؟',1,'2026-02-11 15:26:23','2026-02-11 15:26:23'),(4,2,'five','إلى أي مدى كان هناك توازن بين الجانب النظري والتطبيقي؟',1,'2026-02-11 15:26:44','2026-02-11 15:26:44'),(5,2,'five','كيف تقيّم جودة الأنشطة والتطبيقات العملية؟',1,'2026-02-11 15:27:07','2026-02-11 15:27:07'),(6,2,'five','إلى أي مدى استفدت فعليًا من محتوى البرنامج؟',1,'2026-02-11 15:27:19','2026-02-11 15:27:19'),(7,1,'five','إلى أي مدى كان شرح المدرب واضح وسهل الفهم؟',1,'2026-02-15 16:57:32','2026-02-15 16:58:38'),(8,1,'five','إزاي تقيّم التزام المدرب بالوقت وإدارته للجلسة؟',1,'2026-02-15 16:59:02','2026-02-15 16:59:02'),(9,1,'five','إلى أي مدى استخدم المدرب أمثلة أو مواقف عملية ساعدتك تفهم أكتر؟',1,'2026-02-15 16:59:19','2026-02-15 16:59:19'),(10,1,'five','إلى أي مدى شجعك المدرب على المشاركة وطرح الأسئلة؟',1,'2026-02-15 17:00:09','2026-02-15 17:00:09'),(11,1,'five','إزاي تقيّم طريقة تعامل المدرب مع الأسئلة والاختلاف في الآراء؟',1,'2026-02-15 17:00:32','2026-02-15 17:00:32'),(12,1,'five','إلى أي مدى حسيت إن الجلسة كانت مساحة آمنة إنك تعبر عن رأيك؟',1,'2026-02-15 17:00:49','2026-02-15 17:00:49'),(13,3,'text','إيه أكتر حاجة شفتها إيجابية في التدريب أو في أسلوب المدرب؟',1,'2026-02-15 17:03:21','2026-02-15 17:03:21'),(14,3,'text','من وجهة نظرك، إيه النقط اللي محتاجة تتحسن في التدريب أو في أداء المدرب؟',1,'2026-02-15 17:03:33','2026-02-15 17:03:33'),(15,3,'text','هتطبق إيه من اللي اتعلمته في شغلك خلال الفترة الجاية؟',1,'2026-02-15 17:03:47','2026-02-15 17:10:11'),(16,3,'ten','على مقياس من 0 إلى 10، قد إيه ممكن ترشح المدرب يقدّم تدريب تاني لزمايلك ؟',1,'2026-02-15 17:07:22','2026-02-15 17:07:22');
