INSERT INTO `instructors` VALUES (1,'2B Academy- don\'t use it please create profile for each trainer','training112@2b.com.eg','Instructor/Go5nBw1yNgukIuLt3RIO1f4a333a6874efeb6c7e49f7e253d0ae.png','<p><strong>نبذة عن هدف تو بي اكاديمي</strong></p>','ادارة التعليم والتطوير','2025-10-05 10:07:20','2026-07-16 11:04:24'),(2,'Ahmed Zidan','trainer.ahmedzidan@gmail.com','Instructor/yRqeRgTSwruzQIQhiCwz62ae31d9af4f48b46149b7d4996d2067.png','<p>أحمد زيدان<br />خبرة أكثر من 17 سنة في مجال التدريب والتطوير في الشركات في مصر والوطن العربي مدير التعليم والتطوير بمجموعة من الشركات<br />محترف معتمد في تطوير المواهب (CPTD من جمعية تنمية المواهب الأمريكية (ATD)<br />مدرب معتمد من اسلسكا بيزنس سكول ومن وزارة الاتصالات في مصر دربت آلاف المتدربين في مصر وفي الوطن العربي علي مجالات الإدارة والقيادة والتدريب والبيع وخدمة العملاء وتصميم البرامج التدربية والمهارات الشخصية</p>','مدير التعليم والتطوير','2025-10-28 11:14:07','2025-10-28 11:14:07'),(3,'Hatem El-sholkamy','H.elsholkamy@2b.com.eg','Instructor/zv0KWWLm7iBDmw42Qbgr612a01a57c3f8812f56e8267a0ef11a6.PNG','<p>&nbsp; &nbsp;</p>','2B Trainer','2025-12-04 10:04:31','2025-12-04 10:04:31'),(4,'Dr. Mohammed Grida','grida@2b.com.eg','Instructor/cqDcXh7P5YmtEJ17H7av34619976004e107f446843b165b0d10d.jpeg','<p style=\"text-align: left;\">.Mohamed Grida is the CEO of 2B and a Professor of Industrial Engineering specializing in supply chain, system dynamics, blockchain, and technology management. He has extensive experience leading industry ventures while contributing to academia through research and teaching</p>','CEO','2026-02-05 15:48:16','2026-02-05 15:48:16'),(5,'Mr. Ahmed Awad','ahmedawad185@gmail.com','Instructor/KvSzSO4kUaUqf7FjXjTs4373fc0f1613ef846d6dde737eb0a3d8.PNG','<p>Mr. Ahmed Awad</p>','English Trainer','2026-02-11 14:22:27','2026-02-11 14:22:27'),(6,'محمود عبد العزيز','m.abdelaziz@2b.com.eg','Instructor/Ed7Nb4IcFvW4t9GLCBFEc1403f4f847512d94dcb07294ab1d781.png','<p>مدير قسم شراكات FinTech</p>','مدير قسم شراكات FinTech','2026-02-12 12:33:53','2026-02-12 12:33:53'),(7,'Inact house','info@inacthouse.com','Instructor/UAK4hTdLXUHpQkVyqpFY775b9375d9877eea2b77a68883512e84.png','<p style=\"direction: ltr;\">They are Business training &amp; Consultancy Company that helps you to achieve Effective &amp; Efficient results.</p>','Training & Consultancy Company','2026-02-12 14:14:49','2026-02-12 14:14:49'),(8,'Heba','training@2b.com.eg','Instructor/EvPHWSU6XXPW3Ozu22ni1f9c1c06a09a16c3bb65b1bd3e687097.png','<p>Heba</p>','English Trainer','2026-02-12 15:14:42','2026-02-12 15:14:42'),(9,'OD Practitioners','hello@odpract.com','Instructor/GU51EcN2DiMoCwO0cI538a0fcd8382ec7c385d63fab2d3b2babc.png','<div class=\"QpPSMb\">\r\n<div class=\"DoxwDb\">\r\n<div class=\"PZPZlf ssJ7i B5dxMb\" role=\"heading\" aria-level=\"2\" data-attrid=\"title\">\r\n<div class=\"elementor-element elementor-element-7c47dd3 elementor-widget elementor-widget-heading\" data-id=\"7c47dd3\" data-element_type=\"widget\" data-widget_type=\"heading.default\">\r\n<div class=\"elementor-widget-container\">\r\n<h2 class=\"elementor-heading-title elementor-size-default\" style=\"direction: ltr; text-align: left;\">About us</h2>\r\n</div>\r\n</div>\r\n<div class=\"elementor-element elementor-element-8201cc9 elementor-widget elementor-widget-text-editor\" data-id=\"8201cc9\" data-element_type=\"widget\" data-widget_type=\"text-editor.default\">\r\n<div class=\"elementor-widget-container\">\r\n<p style=\"direction: ltr; text-align: left;\">We&rsquo;re on a mission to be the most relevant Organization Development organization in Egypt. We help individuals to improve their leadership talent, strategic thinking and organizational culture. OD Practitioners (ODP) has executive education programs that are consistently ranked among the best between Human Resources world. Everything we do is depended on scientific background by some of the best professional &amp; academic trainers in the HR field.</p>\r\n<p style=\"direction: ltr; text-align: left;\">The OD Practitioners (ODP) is a comprehensive and authoritative learning organization supporting the broad OD Practitioners specially and Human Resources Professionals Community Generally across foundational education, career expertise, and professional development.</p>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>','Training & Consultancy Company','2026-02-13 12:10:27','2026-02-13 12:10:27'),(10,'Heba Ezzat','heba@hebaedu.com','Instructor/MODxv0xf4Do6yAd5emv2aca13d0f4a52c593834f1432b708e111.jfif','<p style=\"text-align: left;\"><strong>Heba Mahmoud Ezzat</strong> is a <strong>Microsoft Certified Trainer (MCT)</strong> with over <strong>30 years of experience</strong> in corporate training, IT, and project management. She specializes in <strong>Microsoft Office applications</strong>, particularly <strong>Excel, Project, Office 365</strong>, and modern collaboration tools such as <strong>Microsoft Teams, Viva, and Power Automate</strong>.</p>\r\n<p style=\"text-align: left;\">She designs and delivers training programs using <strong>ADDIE</strong> and <strong>adult learning principles</strong>, with a strong focus on <strong>practical application, process automation, and performance improvement</strong>. Her professional background includes leadership roles in <strong>training, IT operations, and service delivery</strong>, as well as experience as a <strong>university instructor</strong> and corporate consultant</p>\r\n<p style=\"text-align: left;\">She has supported a wide range of organizations across corporate, governmental, and NGO sectors, helping teams improve productivity, collaboration, and decision-making through technology-enabled learning</p>\r\n<h3 style=\"text-align: right;\" data-start=\"107\" data-end=\"126\">نبذة عن المدربة</h3>\r\n<p style=\"text-align: right;\" data-start=\"128\" data-end=\"453\"><strong data-start=\"128\" data-end=\"145\">هبة محمود عزت</strong> مدربة معتمدة من مايكروسوفت (<strong data-start=\"174\" data-end=\"211\">Microsoft Certified Trainer &ndash; MCT</strong>) تمتلك خبرة تزيد عن <strong data-start=\"232\" data-end=\"244\">30 عامًا</strong> في التدريب المؤسسي، وتقنية المعلومات، وإدارة المشروعات. تتخصص في تطبيقات <strong data-start=\"318\" data-end=\"338\">Microsoft Office</strong>، وبشكل خاص <strong data-start=\"350\" data-end=\"382\">Excel، وProject، وOffice 365</strong>، وأدوات التعاون الحديثة مثل <strong data-start=\"411\" data-end=\"452\">Microsoft Teams وViva وPower Automate</strong>.</p>\r\n<p style=\"text-align: right;\" data-start=\"455\" data-end=\"750\">تقوم بتصميم وتنفيذ البرامج التدريبية وفق نموذج <strong data-start=\"502\" data-end=\"511\">ADDIE</strong> ومبادئ <strong data-start=\"519\" data-end=\"534\">تعلم الكبار</strong>، مع التركيز على <strong data-start=\"551\" data-end=\"598\">التطبيق العملي، وأتمتة العمل، وتحسين الأداء</strong>. شغلت عدة مناصب قيادية في التدريب وتشغيل تقنية المعلومات، كما عملت كمحاضِرة جامعية ومستشارة تدريبية، وقدمت برامجها لجهات محلية ودولية في قطاعات مختلفة.</p>','Trainer','2026-02-17 14:55:11','2026-02-17 14:55:11'),(11,'احمد هاني محمد','ahmed.hany@2b.com.eg','Instructor/koNg62D0Bj2ne1DQ0df2003ed21b8f45ed41916b6c11f0a2fad8.jpg','<p>senior Business Developer</p>','senior Business Developer','2026-02-22 13:12:10','2026-02-22 13:12:10'),(12,'الجمعية المصرية للمالية العامة والضرائب','Tax@tax.com','Instructor/SJNeas59CgEpw3fnUvdda0d4acee8c84578be7d8e8689d8c4b82.jpg','<div class=\"QpPSMb\">\r\n<div class=\"DoxwDb\">\r\n<div class=\"PZPZlf ssJ7i xgAzOe\" role=\"heading\" aria-level=\"2\" data-attrid=\"title\"><span dir=\"rtl\">الجمعية المصرية للمالية العامة والضرائب</span></div>\r\n</div>\r\n</div>\r\n<div class=\"nwVKo\">\r\n<div class=\"loJjTe\">&nbsp;</div>\r\n</div>','Training & Consultancy Company','2026-02-25 11:01:30','2026-02-25 11:01:30'),(13,'Dr. Ahmed Ragab','trainer--@gmail.com','Instructor/FHgBeGwxL5kOFohxU7u092492eead4a6124a8a6a011f2242aaa7.jpg','<p style=\"text-align: left;\">A professional with 25 years of experience in sales within the medical and pharmaceutical industries, working with multinational corporations, SMEs, and startups across Egypt, KSA, and Bahrain, progressing from entry-level roles to director positions. Since earning an MSc in Strategic Global Human Resources Management from the <span class=\"hover:entity-accent entity-underline inline cursor-pointer align-baseline\"><span class=\"whitespace-normal\">University of Liverpool</span></span> in 2012, he has delivered over 10,000 training hours for more than 65 organizations across Egypt, KSA, Jordan, and the UAE. In 2016, he earned the Professional Certificate of Training from the <span class=\"hover:entity-accent entity-underline inline cursor-pointer align-baseline\"><span class=\"whitespace-normal\">American University in Cairo</span></span> with an excellent grade, enhancing his training methodologies. He currently provides training and consulting through <span class=\"hover:entity-accent entity-underline inline cursor-pointer align-baseline\"><span class=\"whitespace-normal\">ESLSCA University</span></span> Executive Education, delivering programs in sales, sales management, marketing, strategic management, people management, and leadership, as well as Train-the-Trainer (TOT) programs across multiple industries and organizational levels.</p>','Professional Trainer','2026-03-15 10:10:16','2026-04-02 10:18:58'),(15,'IBAS','admissions@ibas.edu.eu','Instructor/gCNhm6fr34RxMg9bTU2Jf3402ed3990a7b506c12b2d78d40db39.png','<div class=\"fusion-layout-column fusion_builder_column fusion-builder-column-5 fusion_builder_column_1_2 1_2 fusion-flex-column\">\r\n<div class=\"fusion-column-wrapper fusion-flex-justify-content-flex-start fusion-content-layout-column\">\r\n<div class=\"fusion-text fusion-text-9\">\r\n<p>This degree is offered either directly as an IBAS qualification or students can choose to add on top-ups or 2-in- 1 degree in collaboration with several partner institutions, enabling students to select the pathway that best aligns with their individual needs and aspirations.</p>\r\n</div>\r\n</div>\r\n</div>\r\n<div class=\"fusion-layout-column fusion_builder_column fusion-builder-column-6 fusion_builder_column_1_2 1_2 fusion-flex-column\">\r\n<div class=\"fusion-column-wrapper fusion-flex-justify-content-flex-start fusion-content-layout-column\">\r\n<div class=\"fusion-builder-row fusion-builder-row-inner fusion-row fusion-flex-align-items-flex-start\">\r\n<div class=\"fusion-layout-column fusion_builder_column_inner fusion-builder-nested-column-8 fusion_builder_column_inner_1_3 1_3 fusion-flex-column\">\r\n<div class=\"fusion-column-wrapper fusion-flex-justify-content-flex-start fusion-content-layout-column\">&nbsp;</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>','Educational institution','2026-03-24 13:14:28','2026-03-24 13:14:28'),(16,'جمعية الضرائب المصرية','training1@gmail.com','Instructor/3gPfc7XeKiyMVEcf2eVIdb07a82e578bb53f6cb366c4434f2186.jpg','<p>جمعية الضرائب المصرية</p>','Training & Consultancy Company','2026-03-24 13:19:57','2026-03-24 13:19:57'),(17,'Mr. Mohamed Mansour','mmansour@promarquee.com','Instructor/Qm9Z4ft2bTrHOaqF2ul7f28e4296f5557d41b82313bf6bc788a9.png','<div class=\"\" data-turn-id-container=\"b184b13e-f41f-4986-9c5a-887719124071\" data-is-intersecting=\"true\">\r\n<div class=\"relative w-full overflow-visible\">\r\n<section class=\"text-token-text-primary w-full focus:outline-none has-data-writing-block:pointer-events-none [&amp;:has([data-writing-block])&gt;*]:pointer-events-auto R6Vx5W_threadScrollVars scroll-mb-[calc(var(--scroll-root-safe-area-inset-bottom,0px)+var(--thread-response-height))] scroll-mt-(--header-height)\" dir=\"auto\" data-turn-id=\"b184b13e-f41f-4986-9c5a-887719124071\" data-turn-id-container=\"b184b13e-f41f-4986-9c5a-887719124071\" data-testid=\"conversation-turn-1\" data-scroll-anchor=\"false\" data-turn=\"user\"></section>\r\n<div class=\"contents\">&nbsp;</div>\r\n</div>\r\n</div>\r\n<div class=\"\" data-turn-id-container=\"request-WEB:8986f404-98e2-48e1-9de6-9b7f5ab2f771-0\" data-is-intersecting=\"true\">\r\n<div class=\"relative w-full overflow-visible\">\r\n<section class=\"text-token-text-primary w-full focus:outline-none has-data-writing-block:pointer-events-none [&amp;:has([data-writing-block])&gt;*]:pointer-events-auto R6Vx5W_threadScrollVars scroll-mb-[calc(var(--scroll-root-safe-area-inset-bottom,0px)+var(--thread-response-height))] scroll-mt-[calc(var(--header-height)+min(200px,max(70px,20svh)))]\" dir=\"auto\" data-turn-id=\"request-WEB:8986f404-98e2-48e1-9de6-9b7f5ab2f771-0\" data-turn-id-container=\"request-WEB:8986f404-98e2-48e1-9de6-9b7f5ab2f771-0\" data-testid=\"conversation-turn-2\" data-scroll-anchor=\"false\" data-turn=\"assistant\">\r\n<div class=\"text-base my-auto mx-auto pb-10 [--thread-content-margin:var(--thread-content-margin-xs,calc(var(--spacing)*4))] @w-sm/main:[--thread-content-margin:var(--thread-content-margin-sm,calc(var(--spacing)*6))] @w-lg/main:[--thread-content-margin:var(--thread-content-margin-lg,calc(var(--spacing)*16))] px-(--thread-content-margin)\">\r\n<div class=\"[--thread-content-max-width:40rem] @w-lg/main:[--thread-content-max-width:48rem] mx-auto max-w-(--thread-content-max-width) flex-1 group/turn-messages focus-visible:outline-hidden relative flex w-full min-w-0 flex-col agent-turn\">\r\n<div class=\"flex max-w-full flex-col gap-4 grow\">\r\n<div class=\"min-h-8 text-message relative flex w-full flex-col items-end gap-2 text-start break-words whitespace-normal outline-none keyboard-focused:focus-ring [.text-message+&amp;]:mt-1\" dir=\"auto\" tabindex=\"0\" data-message-author-role=\"assistant\" data-message-id=\"8bc11731-670b-4ecc-9326-0ad577944f14\" data-turn-start-message=\"true\" data-message-model-slug=\"gpt-5-5\">\r\n<div class=\"flex w-full flex-col gap-1 empty:hidden\">\r\n<div class=\"markdown prose dark:prose-invert wrap-break-word w-full light markdown-new-styling\">\r\n<p data-start=\"0\" data-end=\"243\"><span class=\"hover:entity-accent entity-underline inline cursor-pointer align-baseline\"><span class=\"whitespace-normal\">Mohamed Mansour</span></span><br data-start=\"37\" data-end=\"40\" />محمد منصور هو مدرب متخصص في تحليل البيانات ومستشار أعمال وخبير في التحول الرقمي، يمتلك خبرة تتجاوز 14 عامًا في مجالات تحليل البيانات، ذكاء الأعمال، تطوير الأعمال، والتدريب المؤسسي عبر العديد من القطاعات.</p>\r\n<p data-start=\"245\" data-end=\"472\">يتميز بخبرة قوية في استخدام أدوات تحليل البيانات مثل Microsoft Power BI وAdvanced Excel وPower Query، مع التركيز على تحويل البيانات إلى رؤى تساعد المؤسسات على اتخاذ قرارات أكثر ذكاءً وتحسين الأداء التشغيلي والتخطيط الاستراتيجي.</p>\r\n<p data-start=\"474\" data-end=\"740\" data-is-last-node=\"\" data-is-only-node=\"\">قدّم أكثر من 6000 ساعة تدريبية في مجالات تحليل البيانات وذكاء الأعمال، وساهم في تطوير مهارات العديد من المحترفين والفرق الإدارية والتنفيذية. كما يمتلك خبرة في التسويق الرقمي، تحليل الأداء، والاستشارات الإدارية، مما جعله مستشارًا موثوقًا للشركات والمديرين التنفيذيين.</p>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n<div class=\"z-0 flex min-h-[46px] justify-start\">&nbsp;</div>\r\n<div class=\"mt-3 w-full empty:hidden\">\r\n<div class=\"text-center\">\r\n<div>\r\n<div class=\"inline-flex border border-gray-100 dark:border-gray-700 rounded-xl\">\r\n<div class=\"bg-token-main-surface-tertiary w-px flex-1 self-stretch\">&nbsp;</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</section>\r\n</div>\r\n</div>','Data Analysis Instructor | Business Consultant','2026-05-18 08:17:04','2026-05-18 08:17:04'),(18,'Dr. Ayman Ayman Saber','Dr.AymanAymanSaber@gmail.com','Instructor/NjHp58xssJUapmRgXTvS2cac1091bf3c4dd813f760603bc64ea4.jfif','<p>Dr. Ayman Ayman Saber</p>','Professional Trainer','2026-06-30 18:17:57','2026-06-30 18:17:57'),(19,'cairo photography club','cairophotographyclub@gmail.com','Instructor/Y1opmuRLPxUQO9QXQYSNccb623644afe2052c69dd0163cbb46e7.png','<p>cairo photography club</p>','Cairo Photo Club','2026-07-16 11:08:23','2026-07-16 11:08:23'),(20,'Mr. Shady Reda','shady.reda@2b.com.eg','Instructor/HfADlNHw5R0ZlIhKZDrv08e7080b98ca71b068fba85f80d0fa9b.jpg','<p>Laptop Product Specialist ... Aligning Hardware with Professional Workflows</p>','Product Manager','2026-07-22 12:05:14','2026-07-22 12:05:14'),(21,'Mr. Ahmed El sherbiny','Ahmed.elsherbiny@2b.com.eg','Instructor/gSv6tRQYaEoEpyttSPKJ3c249ffdf075356d4eca7baba104d81b.jpg','<p data-path-to-node=\"6,0\">Product Manager...Home Appliances, <em data-path-to-node=\"6,1\" data-index-in-node=\"0\">Bridging lifestyle needs with reliable home technology</em></p>','Product Manager','2026-07-22 12:11:03','2026-07-22 12:11:03'),(22,'Mr. Samir Saleh','Samir.saleh@2b.com.eg','Instructor/CvCKgo94YPMU9vF5CyjW75762d4c009cdb5dca9ff2457e85d1cf.jpg','<p>Samir Saleh ... FinTech &amp; Payment Solutions Specialist</p>','Fintech Partnership Specialist','2026-07-22 12:21:36','2026-07-22 12:21:36'),(23,'Mr. Mahmoud Raafat','mahmoud.raafat@2b.com.eg','Instructor/Gu75s6c19Kkxx8Tq8sbl468ed15e0c0a2f849e6f034c280a2e8a.jpg','<p>Mr. Mahmoud Raafat ... Printing &amp; Networking Specialist</p>','Product Manager','2026-07-22 12:33:11','2026-07-22 12:33:11'),(24,'Mr. Anas Afefey','a.afefey@2b.com.eg','Instructor/ypqeEOwpxDaTbP3Wshpb11acfae0dfe9128164abed784ed255ee.jpg','<p>Mr. Anas Afefey</p>','Senior Acc.Product Manager','2026-07-22 12:38:07','2026-07-22 12:38:07'),(25,'Mr. Amr Emad','amr.emad@2b.com.eg','Instructor/hqIkTHj96ystiumFaqoV962d5bb18c3b4ec267541e1b886da9f0.jpg','<p>Mr. Amr Emad</p>','Senior Acc.Product Manager','2026-07-22 12:40:36','2026-07-22 12:40:36'),(26,'Mr. Mohamed Zedan','Mohamed.zedan@2b.com.eg','Instructor/K4Fw5EWbuxt2xoKAjTge3f77382267ec7b231f045b4cbd36c167.jpg','<p>Mr. Mohamed Zedan</p>','Senior Device Product Manager','2026-07-22 12:42:55','2026-07-22 12:42:55'),(27,'Mr. Ziad Tarek','ziad.tarek@2b.com.eg','Instructor/o88sG1up60tfVYI6l2tc5ae8117c46b89b290858fae1b23a654b.jpg','<p>Mr. Ziad Tarek</p>','Assistant  Product Manager','2026-07-22 12:44:44','2026-07-22 12:4