INSERT INTO `public_notifications` VALUES (1,'تعاون جديد مع English Capsules','متحمسين نشارككم خبر جديد 👏\r\nتم التعاون مع English Capsules 💙\r\nعلشان نقدّم تجربة تعلم لغة إنجليزية أقوى، أبسط، وأقرب لاحتياجاتكم.\r\nهي منصة تعليم اللغة الإنجليزية يديرها متخصصون في التدريس ، وتركز على تقديم برامج تعليمية متنوعة تناسب جميع المستويات من مبتدئ لاحترافي، سواء أونلاين أو في الفصول الحقيقي\r\n📽️ فيديو الإعلان في اللنك ده https://2b-academy.com/storage/CourseLecture/1766412339_Capsules%20&%202B.mp4',0,'2025-12-22 16:06:09','2025-12-22 16:06:09'),(2,'من النهاردة التدريب أسهل! 2B Academy','من النهاردة التدريب أسهل! 2B Academy\r\nمساء الخير \r\nده فيديو سريع بيشرح إزاي تستخدموا منصة 2B Academyالجديدة   \r\nhttps://2b-academy.com/storage/CourseLecture/1768127808_Untitled design (2).mp4\r\nهتعرف في الفيديو المعلومات دي:\r\n✅ تسجيل الدخول\r\n🔔 الإشعارات اللي هتوصلكم على HR App\r\n📅 المواعيد\r\n📚 المادة التدريبية\r\n📝 الاختبارات\r\n🎓 الشهادات\r\n\r\nمن فضلكم اتفرجوا على الفيديو، ولو عندكم أي استفسار ابعتولنا علي الاميل ده training@2b.com.eg',0,'2026-01-11 11:47:38','2026-01-11 11:47:38'),(3,'من النهاردة التدريب أسهل! ✅ 2b-academy','من النهاردة التدريب أسهل!  2b-academy\r\nمساء الخير يا جماعة \r\nده فيديو سريع بيشرح إزاي تستخدموا منصة 2B Academyالجديدة   \r\nbit.ly/3YAXW5n\r\nده رابط المنصه https://2b-academy.com/\r\nهتعرف في الفيديو:\r\n✅ تسجيل الدخول\r\n🔔 الإشعارات اللي هتوصلكم على HR App\r\n📅 المواعيد\r\n📚 المادة التدريبية\r\n📝 الاختبارات\r\n🎓 الشهادات\r\n\r\nمن فضلكم اتفرجوا على الفيديو، ولو عندكم أي استفسار ابعتولنا علي الاميل ده training@2b.com.eg',0,'2026-01-11 11:56:22','2026-01-11 11:56:22'),(4,'رابط فيديو شرح 2B Acadmy','رابط فيديو شرح 2B Acadmy  (أسف اني بعت الرسالة أكتر من مرة علشان الرابط مكانش شغال)\r\n\r\nhttps://2b-academy.com/storage/CourseLecture/1768128695_Academy.mp4',0,'2026-01-11 12:05:12','2026-01-11 12:05:12'),(5,'حجز كورسات اللغة الإنجليزية','حجز كورسات اللغة الإنجليزية\r\nمساء الخير \r\nزي ما بلغناكم قبل كده، لو حابب/حابة تاخد كورسات إنجليزي خارج مقر الشركة، إحنا متعاقدين مع مكانين:\r\nEnglish Capsules\r\nفروعهم: مدينة نصر – المعادي – الدقي\r\nEnglisher\r\nوده بيكون أونلاين (مناسب أكتر لو إنت خارج القاهرة الكبرى)\r\n✅ طريقة الحجز:\r\nادخل على اللينك ده وسجّل بياناتك:\r\nحط اللينك هنا\r\nبعد ما تسجّل، إحنا هنبلغ المكان اللي إنت اخترته باسمك، وهما هيتواصلوا معاك علشان ينسقوا المواعيد.\r\nhttps://forms.gle/hkdVoXrXvbfTPtUs7',0,'2026-01-15 12:56:03','2026-01-15 12:56:03'),(6,'حجز كورسات اللغة الإنجليزية','حجز كورسات اللغة الإنجليزية\r\nمساء الخير \r\nزي ما بلغناكم قبل كده، لو حابب/حابة تاخد كورسات إنجليزي خارج مقر الشركة، إحنا متعاقدين مع مكانين:\r\nEnglish Capsules: فروعهم: مدينة نصر – المعادي – الدقي\r\nEnglisher: وده بيكون أونلاين (مناسب أكتر لو إنت خارج القاهرة الكبرى)\r\n✅ طريقة الحجز:\r\nادخل على اللينك ده وسجّل بياناتك:\r\nحط اللينك هنا\r\nبعد ما تسجّل، إحنا هنبلغ المكان اللي إنت اخترته باسمك، وهما هيتواصلوا معاك علشان ينسقوا المواعيد.\r\nhttps://forms.gle/hkdVoXrXvbfTPtUs7',1,'2026-01-15 12:57:41','2026-01-15 12:57:41'),(7,'تنبيه مهم – الساعات التدريبية 2026','تنبيه مهم – الساعات التدريبية 2026\r\nمساء الخير،\r\nيرجى العلم إن عدد الساعات التدريبية المطلوبة خلال عام 2026 لكل موظف هو 60 ساعة.\r\nالساعات التدريبية السنة دي مرتبطة بالتقييم السنوي، وده هيأثر على الزيادة السنوية والترقيات.\r\nبرجاء الالتزام باستكمال الساعات المطلوبة خلال العام.\r\n شكراً.',1,'2026-01-18 16:10:28','2026-01-18 16:10:28'),(8,'تسجيل حضور سيشن شاومي','بفكّركم بضرورة تسجيل حضور سيشن امبارح علشان يتحسب لكم في الساعات التدريبية.\r\n🌐 الدخول على موقع الأكاديمية:\r\nhttps://2b-academy.com/\r\n🔐 تسجيل الدخول بـ:\r\nالكود الوظيفي\r\nنفس الباسورد الخاص بأبلكيشن الـ HR\r\n📚 بعد الدخول:\r\nاضغط على \"دوراتي\"\r\nاضغط على الزر الأخضر \"تسجيل الحضور\"\r\n⚠️ ملحوظة مهمة:\r\nفي حالة عدم تسجيل الحضور، الساعات دي مش هتضاف على ساعاتك التدريبية السنوية.',0,'2026-02-18 11:45:03','2026-02-18 11:45:03'),(9,'Excel course intermediate','مساء الخير بنفكركم بميعاد كورس الاكسيل بكرة \r\nالمواعيد من 1 ظهرا الي 3\r\nالمكان: : 37 شارع عبدالرازق السنهوري متفرع من مكرم عبيد مدينة نصر\r\nاسم المكان: 302Labs Coworking Space\r\nاللوكيشن:https://maps.app.goo.gl/ywbGie9ZxZznQU2F6',0,'2026-02-25 14:13:42','2026-02-25 14:13:42'),(10,'Excel course intermediate','مساء الخير بنفكركم بميعاد كورس الاكسيل بكرة \r\nالمواعيد من 1 ظهرا الي 3\r\nالمكان: : 37 شارع عبدالرازق السنهوري متفرع من مكرم عبيد مدينة نصر\r\nاسم المكان: 302Labs Coworking Space\r\nاللوكيشن:https://maps.app.goo.gl/ywbGie9ZxZznQU2F6',0,'2026-02-25 14:13:58','2026-02-25 14:13:58'),(11,'test','test',0,'2026-02-25 14:14:56','2026-02-25 14:14:56'),(12,'Excel course intermediate','مساء الخير بنفكركم بميعاد كورس الاكسيل بكرة\r\n المواعيد من 1 ظهرا الي 3 \r\nالمكان : 37 شارع عبدالرازق السنهوري متفرع من مكرم عبيد مدينة نصر\r\n اسم المكان: 302Labs Coworking Space\r\n اللوكيشن:https://maps.app.goo.gl/ywbGie9ZxZznQU2F6',0,'2026-02-25 14:16:26','2026-02-25 14:16:26'),(13,'Excel course intermediate','مساء الخير بنفكركم بميعاد كورس الاكسيل بكرة\r\n المواعيد من 1 ظهرا الي 3 \r\nالمكان : 37 شارع عبدالرازق السنهوري متفرع من مكرم عبيد مدينة نصر\r\n اسم المكان: 302Labs Coworking Space\r\n اللوكيشن:https://maps.app.goo.gl/ywbGie9ZxZznQU2F6',0,'2026-02-25 14:19:22','2026-02-25 14:19:22'),(14,'ِAdvanced Excel Course','مساء الخير\r\n بنفكركم بميعاد كورس الاكسيل بكرة\r\n المواعيد من 1 1 صباحا الي 1 ظهرا\r\n المكان: : 37 شارع عبدالرازق السنهوري متفرع من مكرم عبيد مدينة نصر\r\n اسم المكان: 302Labs Coworking Space\r\n اللوكيشن:https://maps.app.goo.gl/ywbGie9ZxZznQU2F6',0,'2026-02-25 14:23:44','2026-02-25 14:23:44'),(15,'English Capsules','مساء الخير\r\nبنفكركم ان النهاردة اخر ميعاد للتسجيل في English Capsules \r\nالان الحجز لعدد معين وباسبقية الحجز',0,'2026-03-09 11:48:26','2026-03-09 11:48:26'),(16,'English Capsules','مساء الخير\r\nبنفكركم ان النهاردة اخر ميعاد للتسجيل في English Capsules \r\nالان الحجز لعدد معين وباسبقية الحجز',0,'2026-03-09 11:48:35','2026-03-09 11:48:35'),(17,'sales management','🔔 تذكير بسيط\r\n\r\nبنحب نفكركم إن دبلومة Sales Management هتبدأ في نفس المواعيد اللي اتبعتت قبل كده، وهي كالتالي:\r\n\r\n📅 1-4-2026\r\n📅 8-4-2026\r\n📅 15-4-2026\r\n📅 16-4-2026\r\n📅 22-4-2026\r\n\r\n⏰ من 11 صباحًا لـ 3 عصرًا\r\n\r\n📍 المكان: فرع كذا – السراج مول – الدور الثاني\r\n\r\n⚠️ مهم:\r\nمن فضلكم ادخلوا على الجروب من اللينك ده، لأن هينزل عليه امتحان صغير دلوقتي، وآخر ميعاد لحله يوم السبت:\r\nhttps://chat.whatsapp.com/ChfEdB3KD6DH4QnKEWhcwz?mode=gi_t',0,'2026-03-26 18:56:15','2026-03-26 18:56:15'),(18,'Public Speaking Course G1','تبيه هام\r\nغدا اول  محاضرة في الكورس \r\nالميعاد الساعة 10\r\nاللوكيشن : الدور السابع في الادارة الميتنج روم الصغيرة\r\nملحوظة :\r\nميعاد المحاضرة الاولي : غدا (6-4-2026)\r\nميعاد المحاضرة الثانية:14-4-2026\r\nميعاد المحاضرة الثالثة:20-4-2026',0,'2026-04-05 15:08:28','2026-04-05 15:08:28'),(19,'VIVO ( V70 FE Training )','حبينا نفكركم بموعد VIVO ( V70 FE Training ) )\r\n\r\nالموضوع: تدريب 2B V70 FE\r\nالوقت: 12:00 ظهراً – 2:00 ظهراً\r\nالمنصة: Google Meet\r\nرابط الحضور\r\nتقدروا تنضموا للاجتماع مباشرة من خلال الرابط ده: https://meet.google.com/qgj-dxfu-bxo',0,'2026-04-08 09:35:22','2026-04-08 09:35:22'),(20,'VIVO ( V70 FE Training )','حبينا نفكركم بموعد VIVO ( V70 FE Training ) )\r\n\r\nالموضوع: تدريب 2B V70 FE\r\nالوقت: 12:00 ظهراً – 2:00 ظهراً\r\nالمنصة: Google Meet\r\nرابط الحضور\r\nتقدروا تنضموا للاجتماع مباشرة من خلال الرابط ده: https://meet.google.com/qgj-dxfu-bxo',0,'2026-04-08 09:35:54','2026-04-08 09:35:54'),(21,'VIVO ( V70 FE Training )','حبينا نفكركم بموعد VIVO ( V70 FE Training ) )\r\n\r\nالموضوع: تدريب 2B V70 FE\r\nالوقت: 12:00 ظهراً – 2:00 ظهراً\r\nالمنصة: Google Meet\r\nرابط الحضور\r\nتقدروا تنضموا للاجتماع مباشرة من خلال الرابط ده: https://meet.google.com/qgj-dxfu-bxo',0,'2026-04-08 09:36:01','2026-04-08 09:36:01'),(26,'Sales Management','مساء الخير يا شباب 👋\r\nحابين نستفيد بأقصى شكل من آخر سيشن في برنامج **Sales Management**،\r\nعشان كده محتاجين منكم نملي الفورم اللي في اللنك ده النهاردة او بكرة باقصي تقدير \r\nhttps://forms.gle/oWi6QFZot1w1GGF69\r\nشكرا',0,'2026-04-23 13:25:38','2026-04-23 13:25:38'),(27,'Sales Management','مهم جداااااا يا شباب كلنا نشارك ونملي الفورم النهاردة\r\n\r\nمساء الخير يا شباب 👋\r\n حابين نستفيد بأقصى شكل من آخر سيشن في برنامج **Sales Management**،\r\n عشان كده محتاجين منكم نملي الفورم اللي في اللنك ده النهاردة او بكرة باقصي تقدير\r\n https://forms.gle/oWi6QFZot1w1GGF69 \r\nشكرا',0,'2026-04-23 16:39:45','2026-04-23 16:39:45'),(28,'INTEL Training','بنفكركم بموعد تدريب INTEL غداً، الاثنين 27 أبريل.\r\n\r\nالوقت: من 12:00 ظهراً حتى 4:00 عصراً.\r\n\r\nالمكان: (Fahem Center)\r\n\r\nيرجى الحضور في الموعد المحدد.',0,'2026-04-26 19:33:34','2026-04-26 19:33:34'),(29,'Sales Management Course','مساء الخير يا جماعة 👋\r\nأهلاً بيكم في Sales Management Course\r\n📅 مواعيد الكورس (من 11 صباحًا لـ 5 مساءً):\r\n10-5-2026\r\n17-5-2026\r\n24-5-2026\r\n7-6-2026\r\n14-6-2026\r\n⚠️ مهم جدًا: الالتزام بالمواعيد والحضور من البداية للنهاية أساسي للاستفادة الكاملة من التدريب.\r\n📍 المكان: 302Labs Coworking Space – مدينة نصر\r\n📌 كل التفاصيل والمواد من هنا:\r\nhttps://chat.whatsapp.com/HbK1aPLmTez2sZorgvqTgl?mode=gi_t\r\n📝 برجاء ملء الاستبيان قبل البداية:\r\nhttps://forms.gle/yWFw7ji1FQHRn4FY8\r\n🧠 اختبار قبلي لتحديد مستواك الحالي\r\n(ادخل عليه وانت جاهز لأنه بيبدأ فورًا):\r\nhttps://2b-academy.com/exam/b6124828-e88d-4791-9db7-e77feece5a06\r\nمستنين التزامكم علشان نطلع بأقصى استفادة 💪',0,'2026-05-05 12:35:57','2026-05-05 12:35:57'),(30,'Sales Management Course','مساء الخير 👋\r\nأهلاً بيكم في Sales Management Course\r\n📅 مواعيد الكورس (من 11 صباحًا لـ 5 مساءً):\r\n\r\n1-6-2026\r\n8-6-2026\r\n15-6-2026\r\n22-6-2026\r\n29-6-2026\r\n\r\n⚠️ مهم جدًا: الالتزام بالمواعيد والحضور من البداية للنهاية أساسي للاستفادة الكاملة من التدريب.\r\n\r\n📍 المكان: 302Labs Coworking Space – مدينة نصر\r\n📌 العنوان:37 شارع عبد الرازق السنهوري، متفرع من مكرم عبيد، مدينة نصر\r\n📍 لينك الموقع: https://maps.app.goo.gl/CGVvg2QjQvHjB4sj6\r\n📌 جروب الواتس اب : https://chat.whatsapp.com/HbK1aPLmTez2sZorgvqTgl?mode=gi_t\r\n📝 برجاء ملء الاستبيان قبل البداية: https://forms.gle/yWFw7ji1FQHRn4FY8\r\n🧠 اختبار قبلي لتحديد مستواك الحالي\r\n(ادخل عليه وانت جاهز لأنه بيبدأ فورًا):\r\nhttps://2b-academy.com/exam/b6124828-e88d-4791-9db7-e77feece5a06\r\nمستنين التزامكم علشان نطلع بأقصى استفادة 💪',0,'2026-05-21 13:27:16','2026-05-21 13:27:16'),(31,'تصحيح','تصحيح \r\nده جروب الواتس اب \r\nhttps://chat.whatsapp.com/Dq47ul0ujhO88dpWUbw5px',0,'2026-05-21 13:30:05','2026-05-21 13:30:05'),(32,'تصحيح','https://chat.whatsapp.com/Dq47ul0ujhO88dpWUbw5px',0,'2026-05-21 13:30:44','2026-05-21 13:30:44'),(33,'تعديل مواعيد Diva Training','📢 إشعار هام – تعديل مواعيد الجلسات\r\n\r\nنود إبلاغكم بأنه تم تعديل مواعيد الجلسات لتصبح كالتالي:\r\n\r\n📅 الجلسة الأولى: 08/06/2026\r\n📅 الجلسة الثانية: 15/06/2026\r\n\r\n⏰ الوقت: من الساعة 11:00 صباحًا إلى 1:00 ظهرًا.\r\n\r\n📍 المكان: كذا – الدور الثاني.\r\n\r\nبرجاء الالتزام بالمواعيد المحددة والحضور قبل موعد الجلسة بوقت كافٍ.\r\n\r\nمع خالص الشكر والتقدير.',0,'2026-06-02 15:51:52','2026-06-02 15:51:52'),(34,'Advanced Excel Course','Advanced Excel Course\r\nصباح الخير بنفكركم ان الكورس هيبدأ الساعة 10 النهاردة في كذا ستور الدور التاني.\r\n\r\nشكرا',0,'2026-06-09 07:35:36','2026-06-09 07:35:36'),(35,'كورس اللغة الانجليزية','الزملاء  الأعزاء،\r\nهنبدأ كورس اللغة الإنجليزية في مقر الشركة بمدينة نصر خلال شهر يوليو، ودي فرصة كويسة لتطوير مهارات اللغة الإنجليزية وتحسين مستوى التواصل في الشغل.\r\nقبل بداية الكورس، هنعمل اختبار تحديد مستوى لكل المتقدمين علشان كل واحد ينضم للمجموعة المناسبة لمستواه.\r\nتفاصيل الكورس:\r\n📌 يوم واحد في الأسبوع\r\n📌 مدة المحاضرة 3 ساعات\r\n📌 المواعيد المتاحة:\r\n•	من 10:00 صباحًا إلى 1:00 ظهرًا\r\n•	من 1:00 ظهرًا إلى 4:00 عصرًا\r\nالكورس بيتكون من 4 مستويات، ومدة كل مستوى من 7 إلى 10 محاضرات حسب خطة المدرب ومستوى تقدم المجموعة.\r\n⏳ آخر موعد للتقديم: الثلاثاء 16 يونيو.\r\nللتسجيل، برجاء ملء النموذج من خلال الرابط التالي:\r\nhttps://forms.gle/GvJgobnEQYnZuq2h8\r\nمستنين مشاركتكم، وبالتوفيق للجميع.\r\nفريق التعلم والتطوير',1,'2026-06-11 09:50:03','2026-06-11 09:50:03'),(36,'بنعتذر عن الخطأ رابط واتس اب محموعة 5 من هنا','بنعتذر عن الخطأ رابط واتس اب محموعة 5 من هنا \r\nhttps://chat.whatsapp.com/JJ2lnvmbcgTHOaE2lzn8Dm',0,'2026-06-24 12:06:55','2026-06-24 12:06:55'),(37,'Sales Management Course – G4','مساء الخير يا جماعة 👋بنفكركم بس بكورس Sales Management Course – G4\r\n\r\n📅 مواعيد الكورس (من 11 صباحًا لـ 5 مساءً):\r\n\r\n• 20-7-2026\r\n• 27-7-2026\r\n• 4-8-2026\r\n• 11-8-2026\r\n• 18-8-2026\r\n\r\n👨‍🏫 المدرب: د. أحمد رجب\r\n\r\n⚠️ مهم جدًا: الالتزام بالمواعيد والحضور من البداية للنهاية أساسي للاستفادة الكاملة من التدريب.\r\n\r\n📍 المكان: 302Labs Coworking Space – مدينة نصر\r\n📌 العنوان:\r\n37 شارع عبد الرازق السنهوري، متفرع من شارع مكرم عبيد، مدينة نصر\r\n\r\n📍 لينك الموقع:\r\nhttps://maps.app.goo.gl/h5qwzdHvmQLV5RSv7\r\n📌 كل التفاصيل والمواد من خلال جروب الواتساب:\r\nhttps://chat.whatsapp.com/LO4yxBYDOj2KTNzpzrVNEE\r\n\r\n📝 برجاء ملء الاستبيان قبل البداية:\r\nhttps://forms.gle/yWFw7ji1FQHRn4FY8\r\n\r\n🧠 اختبار قبلي لتحديد مستواك الحالي\r\n(ادخل عليه وانت جاهز لأنه بيبدأ فورًا):\r\nhttps://2b-academy.com/exam/b6124828-e88d-4791-9db7-e77feece5a06\r\n\r\n🗓️ برجاء إضافة مواعيد التدريب إلى جدولكم والحرص على الحضور في جميع الجلسات.\r\n\r\nمستنين التزامكم علشان نطلع بأقصى استفادة 💪',0,'2026-07-16 08:44:04','2026-07-16 08:44:04'),(38,'تقييم خدمات إدارة التعلم والتطوير (L&D)','صباح الخير \r\nمحتاجين منكم دقيقتين بس لملء استبيان تقييم خدمات إدارة التعلم والتطوير (L&D) عن النصف الأول من 2026.\r\nhttps://forms.gle/HJo4Yh9yunFfKzV87\r\nرأيكم هيساعدنا نطوّر البرامج التدريبية ونحدد احتياجاتكم وخطة التدريب للنصف الثاني من السنة.\r\n\r\nشاكرين وقتكم وتعاونكم 🙏\r\nأحمد زيدان\r\nمدير التعليم والتطوير',1,'2026-07-21 09:24:28','2026-07-21 09:24:28'),(39,'استبيان ادرة التعليم والتطوير','مساء الخير \r\n\r\nتذكير سريع 😊\r\nلو لسه ما كملتش الاستبيان، ياريت تخصص له دقيقتين. رأيك هيفرق معانا في تطوير البرامج التدريبية وخطة التدريب القادمة.\r\n\r\nhttps://forms.gle/W4kFMz1XDnV6VWAu7\r\n\r\nشكرًا لتعاونكم 🙏',1,'2026-07-22 16:38:26','2026-07-22 16:38:26');
