DROP TABLE IF EXISTS `user_course_evaluations`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `user_course_evaluations` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `user_id` bigint unsigned NOT NULL,
  `user_machine_code` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `user_department` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `course_id` bigint unsigned NOT NULL,
  `course_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `instructor_id` bigint unsigned NOT NULL,
  `instructor_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `evaluation_category_id` bigint unsigned DEFAULT NULL,
  `evaluation_category_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `evaluation_id` bigint unsigned NOT NULL,
  `evaluation_title` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `evaluation_type` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT '0',
  `answer` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=3504 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;
